import ctypes
import os

class GSLFunction:
    def __init__(self, func):
        self.func = func
        self.c_func = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)(self._wrap_func)
        self.params = None

    def _wrap_func(self, x, params):
        return self.func(x)

    def get_c_func(self):
        return self.c_func

    def set_params(self, params):
        self.params = params

class CQuadWorkspace:
    def __init__(self, size):
        self.size = size
        try:
            self.gsl = ctypes.CDLL(os.environ.get("GSL_LIB", "/usr/local/gsl/lib/libgsl.so"))
            self.gslcblas = ctypes.CDLL(os.environ.get("GSLCBLAS_LIB", "/usr/local/gsl/lib/libgslcblas.so"), mode=ctypes.RTLD_GLOBAL)
        except OSError as e:
            raise OSError("Could not load GSL libraries. Please check your GSL installation and environment variables.") from e

        self.workspace = self.gsl.gsl_integration_cquad_workspace_alloc(self.size)

    def __del__(self):
        if hasattr(self, 'workspace') and self.workspace:
            self.gsl.gsl_integration_cquad_workspace_free(self.workspace)

    def get_workspace(self):
        return self.workspace

def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    try:
        gsl_function = GSLFunction(func)
        workspace = CQuadWorkspace(workspace_size)

        result = ctypes.c_double()
        abserr = ctypes.c_double()
        nevals = ctypes.c_size_t()

