            gsl_function.get_c_func(),
            a, b,
            epsabs, epsrel,
            workspace.get_workspace(),
            ctypes.byref(result),
            ctypes.byref(abserr),
            ctypes.byref(nevals),
        )

        if status != 0:
            raise RuntimeError(f"GSL integration failed with status code: {status}")

