        try:
            ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
            gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        except OSError as e:
            return f"Error loading GSL libraries: {e}"

        # Define C function signatures
        gsl_integration_workspace_alloc = gsl.gsl_integration_workspace_alloc
        gsl_integration_workspace_alloc.argtypes = [ctypes.c_size_t]
        gsl_integration_workspace_alloc.restype = ctypes.c_void_p

        # Allocate workspace
        workspace = gsl_integration_workspace_alloc(n)

        if workspace is None:
            return "Failed to allocate workspace."

        return workspace

    except ValueError as e:
        return str(e)

def free_workspace(workspace):
