        return "Workspace is NULL."

    try:
        # Load GSL library if not already loaded
        if not hasattr(free_workspace, "gsl"):
            ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
