        # Define C function signature
        gsl_integration_workspace_free = gsl.gsl_integration_workspace_free
        gsl_integration_workspace_free.argtypes = [ctypes.c_void_p]
        gsl_integration_workspace_free.restype = None

        gsl_integration_workspace_free(workspace)
        return "Workspace freed successfully."
    except OSError as e:
        return f"Error loading GSL libraries: {e}"

