        self.func = func
        self.f = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)
        self._as_parameter_ = self.f(self._evaluate)

    def _evaluate(self, x):
        return self.func(x)


def integrate_function(func, a, b):
    try:
        # Load GSL libraries in the specified order
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

