        gsl_integration_qk61.argtypes = [ctypes.c_void_p, ctypes.c_double, ctypes.c_double, ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p]
        gsl_integration_qk61.restype = ctypes.c_int

        # Wrap Python function using GSLFunction class
        gsl_func = GSLFunction(func)

        # Initialize result and error variables
        result = ctypes.c_double(0.0)
        abserr = ctypes.c_double(0.0)
        resabs = ctypes.c_double(0.0)
        resasc = ctypes.c_double(0.0)

        # Perform integration
        status = gsl_integration_qk61(gsl_func._as_parameter_, a, b, ctypes.byref(result), ctypes.byref(abserr), ctypes.byref(resabs), ctypes.byref(resasc))

        if status != 0:
