import numpy as np

class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.data = (ctypes.c_double * (rows * cols))()
        self.matrix = None  # Initialize to None

    def to_gsl(self):
        self.matrix = gsl.gsl_matrix_alloc(self.rows, self.cols)
        for i in range(self.rows):
            for j in range(self.cols):
                gsl.gsl_matrix_set(self.matrix, i, j, self.data[i * self.cols + j])
        return self.matrix

    def from_gsl(self):
        if self.matrix is None:
            raise ValueError("GSL matrix is not initialized.")
        for i in range(self.rows):
            for j in range(self.cols):
                self.data[i * self.cols + j] = gsl.gsl_matrix_get(self.matrix, i, j)
        gsl.gsl_matrix_free(self.matrix)
        self.matrix = None  # Reset after freeing
        return self

    def to_list(self):
        return [[self.data[i * self.cols + j] for j in range(self.cols)] for i in range(self.rows)]

